using System.Net.Http.Json;using System.Text.Json;using SalekhPos.Desktop.Application.Management;namespace SalekhPos.Desktop.Infrastructure.Management;public sealed class HttpBillingManager(HttpClient client):IBillingManager{private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);public async Task<DesktopBillingAccount>CreateAccountAsync(Guid org,string name,string email,string currency,Guid op,Guid id,CancellationToken ct){Ids(org,op,id);using var r=await client.PostAsJsonAsync($"api/v1/organizations/{org:D}/billing/accounts",new{OperationId=op,AccountId=id,LegalName=name,BillingEmail=email,Currency=currency,TaxIdentifier=(string?)null},Json,ct);r.EnsureSuccessStatusCode();var v=await r.Content.ReadFromJsonAsync<DesktopBillingAccount>(Json,ct)??throw new InvalidOperationException("Empty billing response.");if(v.AccountId!=id||v.Currency.Length!=3)throw new InvalidOperationException("Billing response is invalid.");return v;}public async Task<DesktopInvoice>GetInvoiceAsync(Guid org,Guid id,CancellationToken ct){Ids(org,id);using var r=await client.GetAsync($"api/v1/organizations/{org:D}/billing/invoices/{id:D}",ct);r.EnsureSuccessStatusCode();var v=await r.Content.ReadFromJsonAsync<DesktopInvoice>(Json,ct)??throw new InvalidOperationException("Empty invoice response.");if(v.InvoiceId!=id||v.Balance<0||v.GrossAmount<0)throw new InvalidOperationException("Invoice response is invalid.");return v;}private static void Ids(params Guid[] ids){if(ids.Any(x=>x==Guid.Empty))throw new ArgumentException("Billing identifiers are required.");}}